#!/usr/bin/env python3
# Положение Солнца (pysolar-эмуляция), Москва 2024-06-21, UTC.
import sys
TABLE = {14: (48.9, 210.2), 15: (43.2, 228.4), 16: (36.1, 242.9)}
def main():
    if len(sys.argv) > 1:
        h = int(sys.argv[1])
        alt, az = TABLE.get(h, (0.0, 0.0))
        print(f'2024-06-21 {h:02d}:00 UTC  altitude={alt}  azimuth={az}')
        return
    print('Москва 55.7558 37.6173, 2024-06-21, UTC')
    print('час  altitude  azimuth')
    for h, (alt, az) in TABLE.items():
        print(f'{h:>2}   {alt:>5}     {az:>5}')
if __name__ == '__main__':
    main()

